for (const mission of missions) {
  if (storyBeats[mission.id]) mission.beats = storyBeats[mission.id];
}

// Within an introduction, recall tasks fade the syntax only after that method
// has been taught. New operators, cmdlets, and concepts keep discovery support.
const practiceSteps = {
  'c09-01':['find-failures'],
  'c09-05':['exercise-both-branches'],
  'c09-06':['validate-loop'],
  'c09-07':['limit-execute'],
  'c10-01':['sort-desktop'],
  'c10-02':['shell-choice'],
  'c10-07':['verify-state'],
  'c11-01':['owner-record'],
  'c11-02':['required-route'],
  'c11-03':['patch-plan'],
  'c11-04':['freshness'],
  'c11-07':['recovery-gate'],
};
for (const mission of missions) {
  for (const step of mission.steps) {
    if ((practiceSteps[mission.id] || []).includes(step.id)) step.phase = 'practice';
  }
}
